conn = database('MyWarehouse', 'analyst', getenv('DB_PASSWORD'), ...
    'LoginTimeout', 10);
if isopen(conn)
    fprintf('Connected to %s via %s\n', conn.DataSource, conn.Driver);
    tables = sqlfind(conn, 'sales');
    disp(tables)
end
close(conn)

conn = sqlite('results.db', 'create');
execute(conn, ['CREATE TABLE runs (id INTEGER PRIMARY KEY, ' ...
    'name TEXT, score REAL, ts TEXT)']);
data = table([1;2], {'baseline'; 'tuned'}, [0.82; 0.91], ...
    {'2024-05-01'; '2024-05-02'}, ...
    'VariableNames', {'id','name','score','ts'});
sqlwrite(conn, 'runs', data);
best = fetch(conn, 'SELECT * FROM runs ORDER BY score DESC LIMIT 1');
disp(best)
close(conn)

conn = sqlite('results.db');
all = sqlread(conn, 'runs');
rf = rowfilter('score');
high = sqlread(conn, 'runs', 'RowFilter', rf.score > 0.85, 'MaxRows', 100);
fprintf('%d of %d rows scored above 0.85\n', height(high), height(all));
close(conn)

conn = sqlite('results.db');
newRuns = table((3:5)', {'a';'b';'c'}, rand(3,1), ...
    repmat({datestr(now, 'yyyy-mm-dd')}, 3, 1), ...
    'VariableNames', {'id','name','score','ts'});
sqlwrite(conn, 'runs', newRuns);
fprintf('Table now has %d rows\n', ...
    fetch(conn, 'SELECT COUNT(*) AS n FROM runs').n);
close(conn)

conn = sqlite('results.db');
newVals = table(0.97, {'2024-06-01'}, 'VariableNames', {'score','ts'});
rf = rowfilter('name');
sqlupdate(conn, 'runs', newVals, rf.name == "tuned");
disp(fetch(conn, 'SELECT * FROM runs WHERE name = ''tuned'''))
close(conn)

conn = sqlite('results.db');
q = ['SELECT name, AVG(score) AS meanScore, COUNT(*) AS n ' ...
     'FROM runs GROUP BY name HAVING COUNT(*) > 0 ORDER BY meanScore DESC'];
summary = fetch(conn, q, 50);
disp(summary)
close(conn)

conn = sqlite('results.db');
execute(conn, 'BEGIN TRANSACTION');
try
    execute(conn, 'CREATE INDEX IF NOT EXISTS idx_score ON runs(score)');
    execute(conn, 'DELETE FROM runs WHERE score < 0.5');
    execute(conn, 'COMMIT');
catch ME
    execute(conn, 'ROLLBACK');
    rethrow(ME);
end
close(conn)

conn = database('MyWarehouse', '', '');
matches = sqlfind(conn, 'fact_', 'Schema', 'analytics');
disp(matches(:, {'Catalog','Schema','Table','Type'}))
for k = 1:height(matches)
    info = sqlread(conn, matches.Table{k}, 'MaxRows', 5);
    fprintf('%s: %s\n', matches.Table{k}, strjoin(info.Properties.VariableNames, ', '));
end
close(conn)

conn = database('Sales', '', '');
allCustomers = sqlouterjoin(conn, 'customers', 'orders', ...
    'Type', 'left', 'LeftKeys', 'id', 'RightKeys', 'customer_id');
noOrders = allCustomers(ismissing(allCustomers.order_id), :);
fprintf('%d customers have never ordered\n', height(noOrders));
close(conn)

conn = sqlite('results.db');
rf = rowfilter(["score", "name"]);
f = (rf.score >= 0.8) & (rf.name ~= "baseline");
good = sqlread(conn, 'runs', 'RowFilter', f);
fprintf('%d matching rows\n', height(good));
fIn = ismember(rf.name, ["tuned", "final"]);
subset = sqlread(conn, 'runs', 'RowFilter', fIn);
close(conn)

conn = sqlite('results.db');
opts = databaseImportOptions(conn, 'runs');
opts = setoptions(opts, 'SelectedVariableNames', {'name','score'});
opts = setvartype(opts, 'name', 'string');
opts = setoptions(opts, 'score', 'FillValue', 0);
data = sqlread(conn, 'runs', opts);
disp(varfun(@class, data, 'OutputFormat', 'cell'))
close(conn)

conn = sqlite('results.db');
cleaner = onCleanup(@() close(conn));
data = sqlread(conn, 'runs');
process(data);        % close(conn) runs even if this errors
fprintf('Connection open: %d\n', isopen(conn));
